import json, math
from pathlib import Path
from build_course import modules, lessons, SOURCES

ROOT=Path(__file__).resolve().parent
GLOSSARY=[
('SOC / Security Operations Center','Центр или организованный процесс наблюдения за безопасностью: люди, данные, правила, расследования и реагирование. В курсе вы строите небольшой учебный стенд, а не производственную службу.','01-01'),
('SIEM','Система сбора, поиска и анализа событий безопасности. Полезность зависит от подключённых источников и качества обнаружений.','01-01'),
('XDR','Подход, объединяющий телеметрию и реагирование из нескольких источников. Не означает автоматическое доказательство любой атаки.','01-01'),
('Событие / Event','Зафиксированный факт: вход, запуск процесса, изменение файла. Может быть штатным действием.','01-01'),
('Алерт / Alert','Результат применения правила к событию или последовательности событий. Требует проверки контекста.','01-01'),
('Инцидент','Ситуация нарушения безопасности, установленная по совокупности фактов и принятой процедуре оценки.','11-01'),
('Агент / Agent','Компонент на наблюдаемом устройстве. Собирает журналы, инвентаризацию и выполняет локальные проверки.','03-01'),
('Wazuh server / Manager','Принимает события агентов, декодирует их и применяет правила. Служба Linux — wazuh-manager.','02-01'),
('Wazuh indexer','Хранилище индексированных документов, которое обслуживает поиск. Это отдельная роль от анализа правил.','02-01'),
('Dashboard','Веб-интерфейс Wazuh. Позволяет исследовать данные и управлять платформой в рамках выданных прав.','02-03'),
('Filebeat','Компонент доставки обычных алертов из alerts.json на индексатор. Инвентаризация может использовать другой путь.','02-01'),
('Indexer connector','Связь модулей менеджера с индексатором для состояния инвентаризации и уязвимостей в выбранной версии.','06-01'),
('Enrollment / регистрация','Процесс создания доверенной записи агента и его ключа. Отличается от дальнейшей передачи событий.','03-01'),
('Декодер / Decoder','Преобразует исходный формат журнала в поля, с которыми работают правила обнаружения.','07-03'),
('Правило / Rule','Условия анализа события: поля, шаблоны, связи и временные окна. Определяет описание и уровень алерта.','07-02'),
('wazuh-logtest','Средство проверки декодеров и правил на образцах журналов. Результат теста не доказывает доставку события с агента.','07-01'),
('FIM / File Integrity Monitoring','Контроль изменения файлов и метаданных относительно базового состояния. Изменение не всегда вредоносно.','05-01'),
('Baseline / базовое состояние','Зафиксированная точка сравнения: содержимое файлов, конфигурация или ожидаемое поведение.','05-01'),
('Who-data','Дополнение FIM, которое помогает установить пользователя и процесс, связанные с изменением файла.','05-03'),
('SCA / Security Configuration Assessment','Проверка настроек по политикам. Результат passed или failed относится к конкретной проверке, а не ко всей безопасности узла.','06-02'),
('Syscollector','Модуль инвентаризации агента: ОС, пакеты, сетевые сведения и другие поддерживаемые категории.','06-01'),
('CVE','Идентификатор опубликованной уязвимости. Запись о CVE не является доказательством её эксплуатации.','06-03'),
('CVSS','Оценка технической серьёзности уязвимости. Приоритет исправления также зависит от доступности и важности актива.','06-04'),
('CTI / Cyber Threat Intelligence','Данные об угрозах. В Wazuh CTI также используется содержимое для сопоставления инвентаря с уязвимостями.','06-03'),
('IOC / индикатор компрометации','Признак для проверки: адрес, домен, хеш. Совпадение требует оценки свежести, качества и контекста.','10-02'),
('MITRE ATT&CK','База тактик и техник поведения противника. Разметка алерта помогает описать гипотезу и покрытие, но не доказывает атаку.','10-01'),
('CDB-список','Локальный список ключей и необязательных значений, используемый правилами для быстрых проверок совпадений.','10-02'),
('Active Response','Выполнение настроенного действия при определённом обнаружении. Требует контроля области применения и способа отмены.','10-04'),
('Sysmon','Служба и драйвер Microsoft для расширенной телеметрии Windows. Создаёт события, а не выносит вердикт об атаке.','08-01'),
('Windows Event ID','Номер типа события внутри определённого провайдера и канала. Один номер без контекста источника недостаточен.','08-02'),
('auditd','Система Linux Audit для наблюдения за системными действиями. Ей нужны подходящие правила аудита.','09-02'),
('DQL и фильтры событий','Язык и интерфейс поиска по индексированным документам. Синтаксис отличается от запросов к API и WQL.','04-03'),
('WQL / Wazuh Query Language','Фильтрация данных в соответствующих разделах Dashboard, работающих через Wazuh API. Проверяйте синтаксис именно своего экрана.','04-03'),
('False positive','Алерт на допустимую активность при сформулированной цели обнаружения. Снижать шум нужно узкими проверенными исключениями.','11-04'),
('False negative','Пропуск события, которое требовалось обнаружить. Его ищут контрольными сценариями, а не только наблюдением за алертами.','11-04'),
('RBAC','Выдача доступа через роли. В Wazuh важно отдельно учитывать права индексатора и права Wazuh API.','12-01'),
('TLS и CA','TLS защищает соединение; центр сертификации помогает проверить удостоверение сервера. Нужны доверие, подходящее имя и верное время.','12-02'),
('Retention / срок хранения','Период доступности данных. Политики индексов, локальные архивы и резервные копии требуют отдельных решений.','12-03'),
('ISM / Index State Management','Механизм автоматического жизненного цикла индексов: состояния и переходы по возрасту, размеру и другим условиям.','12-03'),
('Snapshot / снимок','Точка восстановления. Снимок VM отличается от снимка индексов и от независимой резервной копии конфигураций.','12-04'),
('EPS / Events Per Second','Количество событий в секунду. Для планирования нужно измерять среднюю нагрузку, пики и долю создаваемых алертов.','13-04'),
('MTTD и MTTR','Метрики времени до обнаружения и до реагирования или восстановления. Значение определяется выбранными точками начала и окончания.','11-03'),
('Triage / первичная оценка','Короткая последовательность проверок: достоверность сигнала, контекст актива, масштаб и следующий шаг.','11-01'),
('Runbook','Проверяемая инструкция расследования или эксплуатации: триггер, действия, ожидаемые результаты, эскалация и откат.','11-03'),
('Корреляция','Связывание нескольких событий по условиям, ключу и временному окну. Ключ без учёта контекста может соединить разные действия.','07-04'),
]

for li, item in enumerate(lessons):
    for qi, question in enumerate(item['quiz']):
        options=question['options']
        shift=(li+qi*2)%len(options)
        question['options']=options[shift:]+options[:shift]
        question['answer']=(question['answer']-shift)%len(options)

data=dict(title='Wazuh Практикум',version='4.14',checked='2026-10-27',modules=modules,lessons=lessons,sources=SOURCES,glossary=[dict(term=a,text=b,lesson=c) for a,b,c in GLOSSARY])
(ROOT/'dist/course.json').write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
total=sum(l['minutes'] for l in lessons)
plan=['# Подробный план обучения Wazuh с нуля','',f'База: Wazuh 4.14. Сверено с официальной документацией 27 октября 2026 года. {len(modules)} модулей, {len(lessons)} уроков, ориентировочно {round(total/60)} часов с самостоятельной практикой.','',
'## Цель','Научиться разворачивать Wazuh в собственной лаборатории, подключать источники, проверять обнаружения, проводить первичное расследование и документировать эксплуатацию.','',
'## До начала','Базовые навыки терминала можно получить в модуле 1. Подготовьте гипервизор, чистую Ubuntu Server 24.04, учебную Windows и локальный защищённый журнал проекта. Центральная VM: ориентир 4 vCPU, 8 GiB RAM, 50 GB; Linux-агент: учебный ориентир 2 vCPU/2 GiB/20 GB; Windows-агент: 2 vCPU/4–6 GiB/50–64 GB. Для всего стенда удобен хост с 24–32 GiB памяти; при меньших ресурсах выполняйте упражнения последовательно.','',
'## Как заниматься','1. Прочитайте объяснение и сформулируйте ожидаемое событие.\n2. Подготовьте копию конфигурации или точку возврата.\n3. Выполните практику на указанном учебном узле.\n4. Проверьте результат на источнике, сервере и в Dashboard.\n5. Запишите доказательство: время, узел, запрос, правило и вывод.\n6. Ответьте на тест, объясните ошибку и повторите непонятный шаг.','',
'## Темп и повторение',f'При 4 часах в неделю — примерно {math.ceil(total/60/4)} нед.; при 8 — {math.ceil(total/60/8)} нед.; при 12 — {math.ceil(total/60/12)} нед. Это оценки без гарантированного срока: отладка стенда может потребовать дополнительного времени. После каждого модуля воспроизведите ключевую практику без подсказки, через неделю повторите проблемные шаги. Все уроки доступны без блокировки.','',
'## Важные соглашения','Адреса, имена и журналы в примерах учебные. Заменяйте заполнители своими значениями. XML-фрагменты добавляются в подходящий существующий раздел конфигурации, а не заменяют весь файл. Сначала проверяются синтаксис и точка отката. Технические примеры курса не исполнялись здесь на реальной установке Wazuh; ожидаемый результат — критерий самостоятельной проверки.','']
elapsed=0
for m in modules:
    ls=[l for l in lessons if l['module']==m['id']]
    start=math.floor(elapsed/60/8)+1
    elapsed+=sum(l['minutes'] for l in ls)
    end=math.ceil(elapsed/60/8)
    plan.extend([f"## Модуль {m['id']:02d}. {m['title']}",'',f"**Цель:** {m['subtitle']}. **Рубеж:** {m['outcome']}",f'При нагрузке 8 ч/нед.: недели {start}–{end}. Объём: {sum(l["minutes"] for l in ls)/60:g} ч.',''])
    for l in ls:
        plan.extend([f"### Урок {l['id'].replace('-','.')}. {l['title']}",'',l['summary'],f"**Время с практикой:** {l['minutes']} мин.",'','**Результаты обучения:**']+['- '+g for g in l['goals']]+['','**Практический маршрут:**','',l['practice'],'','**Критерий готовности:** '+l['expected'],'','**Контроль:**']+['- '+q['question'] for q in l['quiz']]+['','**Доказательства выполнения:**']+['- '+c for c in l['checks']]+['','**Материалы:** '+ '; '.join(f'[{SOURCES[k][0]}]({SOURCES[k][1]})' for k in l['sources']), ''])
plan.extend(['## Правила оценки итоговой работы','Итоговый модуль содержит полную рубрику. Ориентир: не менее 80 из 100 баллов и отсутствие критических пробелов — нет подтверждённой доставки данных, нет проверенных обнаружений или не продемонстрировано восстановление. Результат — самостоятельная учебная оценка, а не официальная сертификация Wazuh.','',
'## Формат учебного журнала','Для каждого эксперимента сохраняйте: цель, дата и пояс, версия, узел, изменение конфигурации, контрольное действие, исходное событие, результат декодирования, rule.id, запрос в Dashboard, вывод и откат. Пароли, ключи и токены храните отдельно.','',
'## Источники','']+ [f'- [{title}]({url})' for title,url in SOURCES.values()])
(ROOT/'dist/wazuh-learning-plan-ru.md').write_text('\n'.join(plan)+'\n',encoding='utf-8')
print(json.dumps(dict(modules=len(modules),lessons=len(lessons),hours=round(total/60,1),words=sum(len((l['theory']+' '+l['practice']).split()) for l in lessons)),ensure_ascii=False))
